-- Run ONCE in DBeaver against the same PostgreSQL DB used by SmartFleetBE.
-- Existing SmartFleet tables are NOT dropped or altered.
-- The existing EF Core model uses quoted PostgreSQL identifiers.

CREATE TABLE IF NOT EXISTS "ArucoMarkerMaps" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "WarehouseId" integer NOT NULL REFERENCES "Warehouses" ("WarehouseID") ON DELETE CASCADE,
    "ArucoId" integer NOT NULL CHECK ("ArucoId" BETWEEN 0 AND 9999),
    "CellCode" varchar(16) NOT NULL,
    "GridColumn" integer NOT NULL CHECK ("GridColumn" BETWEEN 1 AND 40),
    "GridRow" integer NOT NULL CHECK ("GridRow" BETWEEN 0 AND 25),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "UQ_ArucoMarkerMaps_Warehouse_Marker" UNIQUE ("WarehouseId", "ArucoId"),
    CONSTRAINT "UQ_ArucoMarkerMaps_Warehouse_Cell" UNIQUE ("WarehouseId", "GridColumn", "GridRow")
);

CREATE TABLE IF NOT EXISTS "RobotArucoPositions" (
    "RobotId" integer PRIMARY KEY REFERENCES "Robots" ("RobotID") ON DELETE CASCADE,
    "ArucoId" integer NOT NULL CHECK ("ArucoId" BETWEEN 0 AND 9999),
    "SeenAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "IX_RobotArucoPositions_SeenAt"
ON "RobotArucoPositions" ("SeenAt");

-- Optional sanity checks; there should be no rows before configuration:
SELECT COUNT(*) AS mapped_markers FROM "ArucoMarkerMaps";
SELECT COUNT(*) AS observed_robot_positions FROM "RobotArucoPositions";
